async function check(path: string, expected: string): Promise<boolean> {
  try {
    return (await readFile(path, "utf8")) === expected;
  } catch {
    return false;
  }
}

if (process.argv.includes("--check")) {
  const results = await Promise.all([check(openApiPath, openApi), check(clientPath, client)]);
  if (results.some((result) => !result)) {
    throw new Error("OpenAPI or generated client is stale; run npm run api:generate");
  }
} else {
  await mkdir(dirname(clientPath), { recursive: true });
  await Promise.all([writeFile(openApiPath, openApi, "utf8"), writeFile(clientPath, client, "utf8")]);
}
